import argparse
import sqlite3
import requests
import sys
from typing import Dict, List, Optional

def parse_arguments() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description='Export rows from SQLite to HTTP endpoint.')
    parser.add_argument('--db', required=True, help='Path to the SQLite database file')
    parser.add_argument('--table', required=True, help='Table to query')
    parser.add_argument('--filter', action='append', help='Column=Value filter (repeatable)')
    parser.add_argument('--endpoint', required=True, help='HTTP endpoint to POST data')
    parser.add_argument('--api-key', help='API key for X-Api-Key header')
    return parser.parse_args()

def build_filters(filters: List[str]) -> List[tuple]:
    return [(col.split('=')[0].strip(), col.split('=')[1].strip()) for col in filters]

def query_database(db_path: str, table: str, filters: List[tuple]) -> List[Dict[str, str]]:
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    if filters:
        cursor.execute(f"SELECT * FROM {table} WHERE {', AND '.join(f'{col} = ?' for col, _ in filters)}")
    else:
        cursor.execute(f"SELECT * FROM {table}")

    columns = [desc[0] for desc in cursor.description]
    rows = cursor.fetchall()

    return [{col: str(row[i]) for i, col in enumerate(columns)} for row in rows]

def send_request(row: Dict[str, str], endpoint: str, api_key: Optional[str]) -> bool:
    headers = {'Content-Type': 'application/json'}
    if api_key:
        headers['X-Api-Key'] = api_key

    try:
        response = requests.post(endpoint, json=row, headers=headers)
        return 200 <= response.status_code < 300
    except requests.RequestException:
        return False

def main():
    args = parse_arguments()
    filters = build_filters(args.filter) if args.filter else []
    rows = query_database(args.db, args.table, filters)

    successful = 0
    failed = 0

    for row in rows:
        if send_request(row, args.endpoint, args.api_key):
            successful += 1
        else:
            failed += 1

    print(f"sent={successful} failed={failed}")

if __name__ == "__main__":
    main()
